<article class="group overflow-hidden rounded-lg border border-slate-200 bg-white"><a href="{{ route('courses.show',$course) }}" class="block"><div class="aspect-[16/9] overflow-hidden"><x-course-image :course="$course" /></div><div class="p-5"><p class="text-xs font-semibold uppercase tracking-wide text-primary-700">{{ $course->category->name }}</p><h3 class="mt-2 line-clamp-2 min-h-[3rem] text-base font-bold leading-6 text-slate-900 group-hover:text-primary-700">{{ $course->title }}</h3><div class="mt-2 flex items-center gap-2 text-xs text-slate-500"><span>{{ ['beginner'=>'Cơ bản','intermediate'=>'Trung cấp','advanced'=>'Nâng cao'][$course->level] ?? ucfirst($course->level) }}</span><span>·</span><span>{{ $course->students_count ?? 0 }} học viên</span></div><p class="mt-3 truncate text-sm text-slate-500">Giảng viên: <strong class="font-semibold text-slate-700">{{ $course->instructor->name }}</strong></p><div class="mt-4 border-t border-slate-100 pt-4 text-base font-bold {{ $course->is_free?'text-emerald-700':'text-slate-900' }}"><x-price :value="$course->price" :free="$course->is_free"/></div></div></a></article>
